
import React, { useEffect, useRef, useState } from 'react';
import { Badge, Col, Row, Spinner, } from 'react-bootstrap';
import FormLayout from '../../utils/formLayout';
import { paymentContainer } from './formFieldData';
import Table from '../../components/Table';
import { findArrObj, numberWithCommas, showConfirmationDialog, showMessage } from '../../utils/AllFunction';
import { getAddLoanRequest, getHolidayRequest, getLoanListDetailsRequest, getLoanListRequest, getStaffRequest, resetGetAddLoan, resetGetLoanList, resetGetLoanListDetails, resetUpdateAddLoan, updateAddLoanRequest } from '../../redux/actions';
import { usePageTitle, useRedux } from '../../hooks'
import { NotificationContainer } from 'react-notifications';
import _ from 'lodash';
import CustomTabComponent from '../../components/Custom-Component/TabComponent';
import noProfile from '../../assets/images/noprofile_images.jpg';
import { baseURL } from '../../api/ApiConfig';
import { useNavigate } from 'react-router-dom';
import moment from 'moment';

let isPrintClicked = false
let LoanList = false
let PaymentList = false
function Index() {


    const navigate = useNavigate();

    usePageTitle({
        title: 'Loan',
        breadCrumbItems: [
            {
                path: '/loan/status',
                label: 'Loan',
            },
            {
                path: '/loan/status',
                label: 'Loan Status',
                active: true,
            },
        ]
    });

    const { dispatch, appSelector } = useRedux();
    const loginInfo = localStorage.getItem('loginInfo');
    const localData = JSON.parse(loginInfo);
    const pageAccessData = findArrObj(localData?.[0]?.pagePermission, 'url', '/loan/status');
    const accessIds = (pageAccessData?.[0]?.access || '').split(',').map(id => id.trim());// for access create and update and delete actions ['1', '2', '3', '4', '5', '6']
    const branchIdforRole = localData?.[0]?.branchId; // for branch list can only show
    const roleIdforRole = localData?.[0]?.roleId; // for role Permission (1.superadmin)

    const {
        getAddLoanSuccess,
        getAddLoanList,
        getAddLoanFailure,

        updateAddLoanSuccess,
        updateAddLoanFailure,

        getLoanListSuccess,
        getLoanList,
        getLoanListFailure,

        getLoanListDetailsSuccess,
        getLoanListDetails,
        getLoanListDetailsFailure,

        errorMessage
    } = appSelector((state) => ({
        updateAddLoanSuccess: state.addLoanReducer.updateAddLoanSuccess,
        updateAddLoanFailure: state.addLoanReducer.updateAddLoanFailure,
        //loan data
        getAddLoanSuccess: state.addLoanReducer.getAddLoanSuccess,
        getAddLoanList: state.addLoanReducer.getAddLoanList,
        getAddLoanFailure: state.addLoanReducer.getAddLoanFailure,


        getLoanListDetailsSuccess: state.addLoanReducer.getLoanListDetailsSuccess,
        getLoanListDetails: state.addLoanReducer.getLoanListDetails,
        getLoanListDetailsFailure: state.addLoanReducer.getLoanListDetailsFailure,

        getLoanListSuccess: state.addLoanReducer.getLoanListSuccess,
        getLoanList: state.addLoanReducer.getLoanList,
        getLoanListFailure: state.addLoanReducer.getLoanListFailure,

        errorMessage: state.holidayReducer.errorMessage,
    }));

    const columns = [
        {
            Header: 'S.No',
            accessor: 'id',
            Cell: (row) => <div>{row?.row?.index + 1}</div>,
        },
        {
            Header: 'Staff',
            accessor: 'staffName',
            Cell: ({ row }) => (
                <div className="inbox-item-img" style={{ display: 'flex', alignItems: 'center' }}>
                    <img
                        src={row?.original?.staffProfile ? `${baseURL}${row?.original.staffProfile}` : noProfile}
                        alt="staffProfile"
                        className="rounded-circle"
                        crossOrigin="anonymous"
                        onError={(e) => {
                            e.target.onerror = null;
                            e.target.src = noProfile;
                        }}
                        style={{ width: "40px", height: "40px", objectFit: "cover", marginRight: "10px" }}
                    />
                    <div>
                        <div style={{ fontSize: '15px', fontWeight: '600' }}>
                            {row?.original?.staffName}
                        </div>
                        <div style={{ fontSize: '12px', color: '#888' }}>
                            {row?.original?.staffCode}
                        </div>
                    </div>
                </div>
            )
        },
        {
            Header: 'Loan No',
            accessor: 'loanNo',
            sort: true,
        },
        {
            Header: 'Loan',
            accessor: 'loanAmount',
            Cell: ({ value }) => {
                return (
                    <div>
                        {numberWithCommas(value || 0)}
                    </div>
                )
            },
        },
        {
            Header: 'Principal',
            accessor: 'principalAmountPaid',
            Cell: ({ value }) => {
                return (
                    <div>
                        {numberWithCommas(value || 0)}
                    </div>
                )
            },
        },
        {
            Header: 'Interest',
            accessor: 'totalInterestAmount',
            Cell: ({ value }) => {
                return (
                    <div>
                        {numberWithCommas(value || 0)}
                    </div>
                )
            },
        },
        {
            Header: 'Paid',
            accessor: 'totalPaidAmount',
            Cell: ({ value }) => {
                return (
                    <div>
                        {numberWithCommas(value || 0)}
                    </div>
                )
            },
        },
        {
            Header: 'Balance',
            accessor: 'balancePrincipalAmount',
            Cell: ({ value }) => {
                return (
                    <div className={`${value > 0 ? 'text-success' : 'text-danger'}`}>
                        {`Rs. ${numberWithCommas(value || 0)}`}
                    </div>
                )
            },
        },
        {
            Header: 'Action',
            accessor: 'actions',
            Cell: ({ row }) => {
                const isActive = row.original.isActive
                return (
                    <div>
                        {
                            (roleIdforRole == 1 || _.includes(accessIds, '3')) && (
                                <>
                                    {isActive ? <span
                                        className={`text-danger cursor-pointer me-2`}
                                        onClick={() =>
                                            showConfirmationDialog(
                                                `You want to close ${row?.original?.loanNo} loan?`,
                                                () => onClosedForm(row.original),
                                                'Yes'
                                            )
                                        }
                                    >
                                        <i className={'fe-log-out'}></i>
                                    </span> : ''}
                                    <span className="cursor-pointer text-success"
                                        onClick={() => {
                                            onPrint(row);
                                        }}
                                    >
                                        <i className={'fe-printer'}></i>
                                    </span>
                                </>
                            )
                        }
                    </div >
                )
            }
        }
    ];

    const [parentList, setParentList] = useState([]);
    const [isLoading, setIsLoading] = useState(false);
    const [state, setState] = useState({});
    const [parentPaymentList, setParentPaymentList] = useState([]);

    useEffect(() => {
        setIsLoading(true)
        const branchReq = {
            branchId: branchIdforRole,
        }
        dispatch(getStaffRequest(roleIdforRole != 1 && branchReq));
        const req = {
            isActive: 1
        }
        dispatch(getLoanListRequest(req));
        isPrintClicked = false
        LoanList = false
        PaymentList = false
    }, []);


    useEffect(() => {
        if (getAddLoanSuccess) {
            setIsLoading(false);
            const obj = {
                "Staff Name": getAddLoanList[0]?.staffName,
                "Staff Code": getAddLoanList[0]?.staffCode,
                "Contact No": getAddLoanList[0]?.contactNo,
                "Address": getAddLoanList[0]?.address,
                "Designation": getAddLoanList[0]?.designationName,
                "Loan No": getAddLoanList[0]?.loanNo,
                "Loan Date": moment(getAddLoanList[0]?.loanDate).format("DD-MM-YYYY"),
                "Interest Rate": `${getAddLoanList[0]?.interestRate}%`,
                "Loan Amount": `Rs. ${numberWithCommas(getAddLoanList[0]?.loanAmount)}`,
                "Process Fees": `Rs. ${numberWithCommas(getAddLoanList[0]?.processFees)}`,
                "Tenure Period": `${getAddLoanList[0]?.tenurePeriod} Months`,
                "Disbursed Type": getAddLoanList[0]?.disbursedTypeName,
            }
            setState({
                ...state,
                loanDetails: obj,
                staffDetails: getAddLoanList[0]
            })
            LoanList = true;
            dispatch(resetGetAddLoan());
        } else if (getAddLoanFailure) {
            setIsLoading(false);
            LoanList = false;
            dispatch(resetGetAddLoan());
        }
    }, [getAddLoanSuccess, getAddLoanFailure]);

    useEffect(() => {
        if (getLoanListSuccess) {
            setIsLoading(false)
            setParentList(getLoanList);
            PaymentList = true;
            dispatch(resetGetLoanList())
        } else if (getLoanListFailure) {
            setIsLoading(false)
            PaymentList = false;
            dispatch(resetGetLoanList())
        }
    }, [getLoanListSuccess, getLoanListFailure]);

    useEffect(() => {
        if (LoanList && PaymentList && isPrintClicked) {
            const reportState = {
                ...state,
                loanDetails: state.loanDetails,
                staffDetails: state.staffDetails,
                loanDetailsArray: parentPaymentList
            };
            setIsLoading(false)
            navigate('/loan-slip-report', { state: reportState });
        }
    }, [LoanList, PaymentList, isPrintClicked])

    const onPrint = (row) => {
        const req = {
            staffLoanId: row?.original?.staffLoanId
        }
        dispatch(getAddLoanRequest(req));
        dispatch(getLoanListDetailsRequest(req));
        isPrintClicked = true;
        setIsLoading(true)
    }

    useEffect(() => {
        if (getLoanListDetailsSuccess) {
            setState({
                ...state,
                loanDetailsArray: getLoanListDetails
            })
            setParentPaymentList(getLoanListDetails)
            dispatch(resetGetLoanListDetails())
        } else if (getLoanListDetailsFailure) {
            dispatch(resetGetLoanListDetails())
        }
    }, [getLoanListDetailsSuccess, getLoanListDetailsFailure]);

    // Update Loan
    useEffect(() => {
        if (updateAddLoanSuccess) {
            const req = {
                isActive: 1
            }
            dispatch(getLoanListRequest(req));
            showMessage('success', `Updated Successfully`);
            dispatch(resetUpdateAddLoan());
        } else if (updateAddLoanFailure) {
            showMessage('warning', errorMessage);
            dispatch(resetUpdateAddLoan());
        }
    }, [updateAddLoanSuccess, updateAddLoanFailure]);


    const onClosedForm = (data) => {
        const submitRequest = {
            isActive: 0
        }
        dispatch(updateAddLoanRequest(submitRequest, data.staffLoanId));
        // dispatch(deletePaymentHistoryRequest(submitRequest, data?.loanPaymentId))
    };

    const tabContents = [
        {
            title: "Active Loan",
            keyId: 1,
            keyEvent: "activeLoan",
            tableColumns: columns,
            tableData: parentList,
            isActive: 1,
        },
        {
            title: "Closed Loan",
            keyId: 1,
            keyEvent: "closedLoan",
            tableColumns: columns,
            tableData: parentList,
            isActive: 0,
        },
    ];

    const onChangeLoan = (data) => {
        const req = {
            isActive: data?.isActive
        }
        dispatch(getLoanListRequest(req));
    }


    return (
        <React.Fragment>
            <NotificationContainer />
            {isLoading ? <div className='bg-light opacity-0.25'>
                <div className="d-flex justify-content-center m-5">
                    <Spinner className='mt-5 mb-5' animation="border" />
                </div>
            </div> :
                <>
                    <Row>
                        <CustomTabComponent
                            title={false}
                            tabContents={tabContents}
                            activeKey={"activeLoan"}
                            onChange={onChangeLoan}
                        />
                    </Row>
                </>
            }
        </React.Fragment>
    );
}

export default Index;
